import {strategyData,indiaRegionalPaths,indiaContextPaths} from './strategy-data.js?v=20261026-development02';
import {developmentPaths} from './development-data.js?v=20261026-development01';
export {strategyData,indiaRegionalPaths,indiaContextPaths};
export const strategyViews={
 'dev-quality-of-life':[['water','Water and time'],['cascade','Linked opportunities'],['digital','Useful technology'],['evidence','Water-service evidence']],
 'dev-international-aid':[['channels','Forms and channels'],['delivery','From delivery to use'],['coverage','Dated coverage evidence'],['budget','Support the whole service']],
 'dev-international-agreements':[['trade','Border cooperation'],['dates','Different stages, different dates'],['climate','Climate cooperation'],['limits','Commitments and outcomes']],
 'dev-development-approaches':[['power','Who makes decisions?'],['topdown','Coordinated planning'],['bottomup','Local decisions'],['hybrid','Combine capacities']],
 'dev-india-location':[['global','India in the world'],['regional','India and neighbours'],['connections','Wider connections'],['scale','Choose the scale']]
};
export const strategyRequirements=Object.fromEntries(Object.entries(strategyViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const strategyAnimated=(k,v)=>k==='dev-quality-of-life'?v!=='evidence':k==='dev-international-aid'?v==='delivery':k==='dev-international-agreements'?['trade','climate'].includes(v):k==='dev-development-approaches'?v!=='power':k==='dev-india-location'?v==='connections':false;
export const aidSupport=b=>b.training+b.maintenance;
export const timeReleased=(before,after)=>before-after;
const T=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(d,c='#b7ccd1',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#edb193')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}" stroke="#e8eee4"/>`;
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?65:43}" rx="11" fill="#35566b" stroke="#a1bdc7"/>`+T(x+10,y+25,a,12)+(b?T(x+10,y+48,b,11):'');
const title=s=>T(20,29,s,13);
const fig=(b,c)=>`<svg viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#eef2ec" font-family="sans-serif">${b}</g></svg><p class="geo-caption">${c}</p>`;
const link=(u,s)=>`<a href="${u}" target="_blank" rel="noopener">${s}</a>`;
const source=k=>`<p class="geo-caption">${{
 water:link(strategyData.water.source,'WHO/UNICEF JMP 2025: 2024 water-service estimates')+' · '+link(strategyData.water.definitionSource,'WHO: service definition')+'. Rounded global estimates, not current household measurements.',
 aid:link('https://www.oecd.org/en/topics/sub-issues/oda-eligibility-and-conditions/official-development-assistance--definition-and-coverage.html','OECD: ODA definition and concessional support')+'. Aid forms differ; not every loan, remittance or investment is ODA.',
 covax:link(strategyData.covax.source,'CEPI/Gavi/UNICEF/WHO, COVAX closing statement, 19 December 2023')+'. Historical two-dose coverage comparison; COVAX closed 31 December 2023. Delivered doses are not unique people or a causal effect estimate.',
 trade:link('https://www.wto.org/english/tratop_e/tradfa_e/tradfa_e.htm','WTO: Trade Facilitation Agreement')+' · '+link(strategyData.tfa.source,'India ratification, 21 April 2016')+' · '+link(strategyData.tfa.forceSource,'TFA entry into force, 22 February 2017')+'. Not the removal of every tariff or a measured gain for all households.',
 climate:link(strategyData.paris.source,'UNFCCC: Paris Agreement')+'. Adopted 12 December 2015; entered into force 4 November 2016. Plans, implementation and outcomes are distinct.',
 strategy:link('https://www.pib.gov.in/Pressreleaseshare.aspx?PRID=2089254&lang=2&reg=48','Government of India: SBM-G Phase II objectives')+' · '+link('https://www.worldbank.org/en/results/2020/10/16/unleashing-the-power-of-women-collectives-for-rural-development-in-the-indian-state-of-bihar','World Bank: Bihar JEEViKA, October 2020')+'. Programme sources describe aims and community roles, not universal success or pure opposites.',
 india:link(strategyData.india.source,'NCERT: India—size and location, 2025–26 reprint')+' · '+link('https://www.naturalearthdata.com/about/terms-of-use/','Natural Earth, public domain geometry')+'. Generalised orientation; selected neighbours and approximate points. Small islands/detail not fully represented.'
 }[k]}</p>`;
const table=(cap,heads,rows)=>`<details class="geo-chart-values"><summary>Read the source values</summary><table class="geo-data"><caption>${cap}</caption><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></details>`;
const xy=(lon,lat)=>[20+(lon-55)/55*400,60+(42-lat)/42*240];
export function indiaRegional(){let b=title('SOUTH ASIA · SELECTED REGIONAL RELATIONSHIPS')+T(20,50,'North ↑ · generalised country outlines',11)+`<defs><clipPath id="india-region-clip"><rect x="20" y="60" width="400" height="240"/></clipPath></defs><rect x="20" y="60" width="400" height="240" fill="#24495e"/><g clip-path="url(#india-region-clip)">${indiaContextPaths.map(p=>`<path d="${p.d}" fill="${p.code==='IND'?'#d4b496':'#74978e'}" stroke="#d7e1d5" stroke-width="0.9"/>`).join('')}</g>`+T(175,190,'India',17)+T(96,120,'Pakistan',11)+T(314,90,'China',12)+line('M235 140L265 118','#e6e7dc',1)+T(268,118,'Nepal',10)+line('M280 144L317 143','#e6e7dc',1)+T(320,146,'Bhutan',10)+line('M276 166L323 185','#e6e7dc',1)+T(326,196,'Bangladesh',10)+line('M318 186L338 215','#e6e7dc',1)+T(340,225,'Myanmar',11)+line('M208 263L237 276','#e6e7dc',1)+T(242,280,'Sri Lanka',11)+T(50,216,'Arabian',12)+T(60,235,'Sea',12)+T(265,245,'Bay of Bengal',12);const p=xy(77.2,28.6);b+=dot(p[0],p[1],3)+T(153,126,'New Delhi',10)+T(20,328,'Location evidence, not a boundary survey or route map',11);return fig(b,'Real Natural Earth country features reprojected to a regional equirectangular view. Selected labels and an approximate capital marker support orientation; boundaries and islands are generalised.')+source('india');}
export function strategyEvidence(kind='coverage'){
 if(kind==='regional')return indiaRegional();
 if(kind==='water'){let b=title('GLOBAL DRINKING-WATER SERVICES · 2024')+T(20,52,'Rounded estimates · billion people · zero-based bars',11)+T(20,92,'Without safely managed service',13)+`<rect x="20" y="108" width="360" height="32" fill="#edb598"/>`+T(20,162,'2.1 billion',15)+T(20,205,'Of this group: basic service',13)+`<rect x="20" y="221" width="240" height="32" fill="#abc6b3"/>`+T(20,275,'1.4 billion',15)+T(20,327,'Reference year 2024 · report published 2025',11);return fig(b,'WHO/UNICEF JMP estimates at the labelled service levels. Values are rounded; these are not current individual household observations.')+source('water')+table('2024 global service estimates',['Service group','Billion people'],[['Without safely managed','2.1'],['Within that group: basic','1.4']]);}
 if(kind==='dates'){let b=title('AGREEMENTS: DISTINCT STEPS AND DATES')+box(20,65,400,'Trade Facilitation Agreement','Concluded 2013')+box(20,147,400,'India’s TFA ratification','21 April 2016')+box(20,229,400,'TFA entered into force','22 February 2017');return fig(b,'Dated TFA milestones from WTO sources. Conclusion, national ratification and entry into force describe different stages; dates are not a measure of benefits achieved.')+source('trade');}
 let b=title('COVAX CLOSING-STATEMENT COMPARISON')+T(20,53,'Two-dose coverage · percent · 19 December 2023',11);for(const [i,p]of strategyData.covax.groups.entries()){b+=T(20,100+i*95,i?'Global average':'AMC lower-income participants',12)+`<rect x="20" y="${115+i*95}" width="${p.value*3.6}" height="28" fill="${i?'#abc6b3':'#edb598'}"/>`+T(30+p.value*3.6,136+i*95,p.value+'%',13);}b+=line('M20 295H380','#a8c0c6',1)+T(20,317,'0',11)+T(348,317,'100%',11);return fig(b,'Reported historical two-dose coverage for the two labelled populations. Read the reference date, group and percentage denominator before comparing.')+source('covax')+table('COVAX closing statement, December 2023',['Population','Coverage'],[['AMC lower-income participants','57%'],['Global average','67%']]);
}
export function strategyScene(k,v,t=0){if(!strategyViews[k])return '';if(!strategyRequirements[k].includes(v))v=strategyRequirements[k][0];t=strategyAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='',src='water';
 if(k==='dev-quality-of-life'&&v==='evidence')return strategyEvidence('water');if(k==='dev-international-aid'&&v==='coverage')return strategyEvidence('coverage');if(k==='dev-international-agreements'&&v==='dates')return strategyEvidence('dates');if(k==='dev-india-location'&&v==='regional')return indiaRegional();
 if(k==='dev-quality-of-life'){
 if(v==='water'){const mins=120-Math.round(t*9)*10;b=title('WATER COLLECTION AND A DAILY TIME BUDGET')+`<path d="M75 65Q35 115 75 135Q115 115 75 65Z" fill="#a8c9ce"/><rect x="300" y="95" width="90" height="80" rx="10" fill="#c7b59e"/>`+line('M120 135H290')+dot(120+170*t,135)+T(20,220,'Collection: '+mins+' minutes',16)+T(20,264,'Time released: '+timeReleased(120,mins)+' minutes',16)+T(20,325,'Invented example: 120 → 30 minutes per day',12);c='An illustrative service improvement releases time for study, work or rest. It is not a measured national time saving, and how people use the time is not guaranteed.';}
 else if(v==='cascade'){b=title('ONE ACCESS BARRIER CAN AFFECT SEVERAL NEEDS')+box(20,70,180,'Housing / food / water','Safety and security')+box(240,70,180,'Health / time','Ability to participate')+box(120,250,200,'School / employment','Opportunities and costs')+line('M200 100H240M330 140L245 240')+dot(200+40*t,100)+dot(330-85*t,140+100*t)+T(20,331,'Possible linked effects, not identical household outcomes',11);c='A simplified pathway connecting housing, health, education and employment with food/water security. Token timing shows direction, not measured effect sizes.';}
 else{b=title('TECHNOLOGY NEEDS SUPPORTING CONDITIONS')+`<rect x="35" y="90" width="95" height="85" rx="8" fill="#a9c2c1"/><rect x="45" y="100" width="75" height="65" fill="#234257"/>`+box(240,80,180,'Usable connection','Education / work / care')+line('M140 135H235')+dot(140+95*t,135)+box(20,250,400,'Access conditions','Electricity / skills / affordability / reliability');c='Digital access can connect people to opportunities when supporting conditions are present. This is a mechanism, not an observed national broadband or employment result.';}
 }
 if(k==='dev-international-aid'){
 src='aid';
 if(v==='channels'){b=title('DISTINGUISH THE FORM AND THE CHANNEL')+box(20,70,190,'Grant','No repayment debt')+box(230,70,190,'Concessional loan','Favourable terms / debt')+box(20,190,190,'Bilateral','Government → country')+box(230,190,190,'Multilateral','Shared institution')+T(20,314,'Emergency relief and long-term development can differ.',11);c='An introductory classification, not a complete ODA accounting rule. Donor, channel, financing terms and purpose are different dimensions.';}
 else if(v==='delivery'){b=title('FOLLOW SUPPORT THROUGH THE DELIVERY CHAIN')+box(20,65,180,'Resources / supply','Procurement / delivery')+box(240,65,180,'Local capacity','Storage / staff')+box(120,250,200,'Usable service','Access / upkeep / use')+line('M200 100H240M330 140L245 240')+dot(200+40*t,100)+dot(330-85*t,140+100*t)+T(20,330,'Outputs, use and outcomes are different measures.',12);c='Symbolic delivery sequence inspired by international health support. Tokens are stages, not doses, people, coverage or a measured causal health benefit.';src='covax';}
 else{b=title('FUND THE WHOLE SERVICE · INVENTED BUDGET')+T(20,65,'100 teaching units in total',15);const rows=[['Delivery',60],['Training',25],['Maintenance',15]];for(let i=0;i<3;i++)b+=T(20,110+i*65,rows[i][0],13)+`<rect x="140" y="${92+i*65}" width="${rows[i][1]*3.5}" height="25" fill="${i?'#a9c4b2':'#edb79a'}"/>`+T(150+rows[i][1]*3.5,110+i*65,String(rows[i][1]),13);b+=T(20,320,'Allocation is illustrative, not an actual project budget.',11);c='A conserved 100-unit teaching budget: delivery60, training25, maintenance15. Training and upkeep can support use; a non-goods cost is not automatically waste.';}
 }
 if(k==='dev-international-agreements'){
 src=v==='climate'?'climate':'trade';
 if(v==='trade'){b=title('BORDER COOPERATION CAN REDUCE DELAYS')+box(20,70,170,'Exporter','Goods and documents')+box(245,70,175,'Border agencies','Checks / clearance')+line('M195 110H238')+dot(195+43*t,110)+box(100,245,240,'Possible enabling changes','Clear information / coordination')+line('M330 145L240 235')+dot(330-90*t,145+90*t)+T(20,330,'Not every tariff removed; gains depend on implementation.',11);c='A conceptual trade-facilitation pathway. It does not measure clearance time, abolish all controls or guarantee benefits for every group.';}
 else if(v==='climate'){b=title('CLIMATE COOPERATION: PLANS INTO ACTION')+box(20,70,180,'National plans','Contributions / policy')+box(240,70,180,'Cooperation','Finance / capability')+box(120,250,200,'Action and reporting','Review actual results')+line('M200 100H240M330 140L245 240M120 280L75 140')+dot(200+40*t,100)+dot(330-85*t,140+100*t)+dot(120-45*t,280-140*t)+T(20,330,'A repeated policy cycle, not a guaranteed climate outcome.',11);c='Illustrative Paris-framework cycle. National actions, finance and reporting differ from signing, and implementation does not automatically achieve every target.';}
 else{b=title('CHECK WHAT HAPPENED AFTER AGREEMENT')+box(20,65,400,'Commitments','Rules / responsibilities / support')+box(20,155,400,'Implementation','Resources / capacity / participation')+box(20,245,400,'Outcomes','Who gained? What changed? What remains?');c='A static evaluation framework. Inter-governmental cooperation can address shared problems, but commitments are not completed outcomes.';}
 }
 if(k==='dev-development-approaches'){
 src='strategy';
 if(v==='power'){b=title('FOLLOW DECISION-MAKING, NOT ONLY THE MONEY')+box(20,70,190,'Top-down leadership','Government / TNC')+box(230,70,190,'Bottom-up leadership','Community decisions')+box(20,200,400,'Ask who has influence','Priorities / resources / challenge / representation')+T(20,320,'Real programmes can combine these elements.',12);c='An introductory comparison of decision-making roles. Funding and influence are distinct; a community committee does not guarantee equal representation.';}
 else if(v==='topdown'){b=title('COORDINATE STANDARDS AND WIDER SYSTEMS')+box(100,65,240,'Government / TNC leadership','Planning / finance / expertise')+box(20,245,180,'Place A','Local needs and costs')+box(240,245,180,'Place B','Local needs and costs')+line('M180 140L110 235M260 140L330 235')+dot(180-70*t,140+95*t)+dot(260+70*t,140+95*t)+T(20,330,'Scale helps coordination; consultation still matters.',11);c='Top-down coordination can support networks and common standards. This is not a guarantee of equal benefits, successful relocation or full local participation.';}
 else if(v==='bottomup'){b=title('LOCAL PRIORITIES, FEEDBACK AND CAPACITY')+box(20,70,180,'Residents / groups','Knowledge and needs')+box(240,70,180,'Local decisions','Design / operation')+box(120,250,200,'Accountability','Who is included?')+line('M200 100H240M330 140L245 240M120 280L75 140')+dot(200+40*t,100)+dot(330-85*t,140+100*t)+dot(120-45*t,280-140*t)+T(20,330,'Finance, technical support and representation can limit reach.',10);c='A community decision-and-feedback loop. Local fit can help, but funding, technical capacity and unequal influence must be assessed.';}
 else{b=title('COMBINE WIDER SUPPORT WITH LOCAL INFLUENCE')+box(20,70,180,'Public / external support','Finance / standards')+box(240,70,180,'Community institutions','Priorities / operation')+box(120,250,200,'Evaluate outcomes','Use / fairness / upkeep')+line('M110 140L185 240M330 140L255 240')+dot(110+75*t,140+100*t)+dot(330-75*t,140+100*t)+T(20,330,'SBM-G and JEEViKA contain different decision-making roles.',10);c='Hybrid arrangements can combine capacities. Named Indian programmes illustrate different elements; official aims and project reports do not establish universal success.';}
 }
 if(k==='dev-india-location'){
 src='india';
 if(v==='global'){b=title('INDIA · SOUTH ASIA IN A GLOBAL VIEW')+T(20,50,'North ↑ · country outlines generalised',11);for(const p of developmentPaths)b+=`<path d="${p.d}" fill="${p.code==='IND'?'#efb194':'#6b918b'}" stroke="#234355" stroke-width="0.45"/>`;const ey=55+85/145*200,cy=55+(85-23.5)/145*200;b+=line(`M20 ${ey}H420`,'#ced8ca',1)+line(`M20 ${cy}H420`,'#e6c1a1',1)+T(24,ey+13,'Equator 0°',10)+T(24,cy-5,'Tropic of Cancer ~23.5°N',10)+line('M315 145L348 162','#f0d3b9',1)+T(350,174,'India',13)+T(20,308,'India lies north of the Equator and east of 0° longitude.',11);c='Real Natural Earth world outlines with India highlighted. The geographic region South Asia does not imply the Southern Hemisphere. Equirectangular projection distorts areas.';}
 else if(v==='connections'){b=title('INDIAN OCEAN POSITION AND WIDER LINKS')+box(120,150,200,'India','Regional / global links')+box(20,65,180,'Westward partners','Africa / Middle East')+box(240,65,180,'Other connections','Europe / East Asia')+line('M110 140L175 145M330 140L265 145')+dot(110+65*t,140+5*t)+dot(330-65*t,140+5*t)+T(20,295,'Conceptual links: no proportional trade values.',12)+T(20,325,'Connections do not guarantee equal access or benefits.',11);c='Symbolic international connections, not a shipping map, measured trade volumes or every route. India’s ocean position is one part of its wider relationships.';}
 else{b=title('SEPARATE CITY, COUNTRY, REGION AND WORLD')+box(20,65,175,'Mumbai','A city within India')+box(245,65,175,'India','A country')+box(20,235,175,'South Asia','A wider region')+box(245,235,175,'Global context','Worldwide relationships')+line('M195 95H240M330 140L110 225M200 270H240');c='Conceptual scale relationships, not nested area shapes or actual boundaries. A city is not the whole country and South Asia contains several countries.';}
 }
 return fig(b,c)+source(src);
}
